// build.gradle — Gradle project configuration (Groovy DSL)
plugins {
    id 'java'
    id 'org.springframework.boot' version '3.2.0'
    id 'io.spring.dependency-management' version '1.1.4'
    id 'jacoco'
}

group = 'com.mycompany'
version = '1.2.0-SNAPSHOT'

java {
    sourceCompatibility = '17'
}

repositories {
    mavenCentral()
}

dependencies {
    implementation 'org.springframework.boot:spring-boot-starter-web'
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
    testImplementation 'org.junit.jupiter:junit-jupiter:5.10.0'
}

tasks.named('test') {
    useJUnitPlatform()
    testLogging {
        events "passed", "skipped", "failed"
    }
}

// Custom task for DevOps: print dependency tree
task printDeps {
    doLast {
        configurations.runtimeClasspath.resolvedConfiguration.firstLevelModuleDependencies.each {
            println "${it.moduleGroup}:${it.moduleName}:${it.moduleVersion}"
        }
    }
}

// Docker image build task (using Palantir Gradle Docker plugin)
docker {
    name "myregistry.com/myapp:${version}"
    files jar.archiveFile
    buildArgs(['JAR_FILE': "${jar.archiveFileName.get()}"])
}

// Jenkinsfile — Declarative Pipeline for Python + Java project
pipeline {
    agent any  // Run on any available agent

    options {
        buildDiscarder(logRotator(numToKeepStr: '10'))
        timeout(time: 30, unit: 'MINUTES')
        disableConcurrentBuilds()
    }

    environment {
        DOCKER_REGISTRY = 'myregistry.com'
        PYTHON_IMAGE = 'myregistry.com/python-api'
        JAVA_IMAGE = 'myregistry.com/java-backend'
        KUBECONFIG = credentials('kubeconfig-prod')
        SONAR_TOKEN = credentials('sonarqube-token')
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
                sh 'git log --oneline -5'
            }
        }

        stage('Build Python API') {
            steps {
                dir('python-api') {
                    sh 'python -m pip install -r requirements.txt'
                    sh 'python -m pytest tests/ --cov=app --cov-report=xml'
                }
            }
            post {
                always {
                    junit 'python-api/test-results.xml'
                    cobertura coberturaReportFile: 'python-api/coverage.xml'
                }
            }
        }

        stage('Build Java Backend') {
            steps {
                dir('java-backend') {
                    sh 'mvn clean verify'
                }
            }
            post {
                always {
                    junit 'java-backend/target/surefire-reports/*.xml'
                }
            }
        }

        stage('Parallel Tests') {
            parallel {
                stage('Python Security Scan') {
                    steps {
                        dir('python-api') {
                            sh 'bandit -r app/ -f json -o bandit-report.json || true'
                            sh 'safety check --json --output safety-report.json || true'
                        }
                    }
                }
                stage('Java Security Scan') {
                    steps {
                        dir('java-backend') {
                            sh 'mvn org.owasp:dependency-check-maven:check'
                        }
                    }
                }
                stage('SonarQube Analysis') {
                    steps {
                        withSonarQubeEnv('SonarQube') {
                            sh '''
                                sonar-scanner \
                                  -Dsonar.projectKey=devops-app \
                                  -Dsonar.sources=python-api,app,java-backend/src \
                                  -Dsonar.python.coverage.reportPaths=python-api/coverage.xml
                            '''
                        }
                    }
                }
            }
        }

        stage('Build Docker Images') {
            steps {
                script {
                    def version = sh(
                        script: 'git describe --tags --always',
                        returnStdout: true
                    ).trim()

                    env.VERSION = version

                    // Build Python image
                    dir('python-api') {
                        sh "docker build -t ${PYTHON_IMAGE}:${version} ."
                        sh "docker tag ${PYTHON_IMAGE}:${version} ${PYTHON_IMAGE}:latest"
                    }

                    // Build Java image
                    dir('java-backend') {
                        sh "docker build -t ${JAVA_IMAGE}:${version} ."
                        sh "docker tag ${JAVA_IMAGE}:${version} ${JAVA_IMAGE}:latest"
                    }
                }
            }
        }

        stage('Push Images') {
            when {
                branch 'main'
            }
            steps {
                script {
                    docker.withRegistry("https://${DOCKER_REGISTRY}", 'registry-credentials') {
                        sh "docker push ${PYTHON_IMAGE}:${env.VERSION}"
                        sh "docker push ${PYTHON_IMAGE}:latest"
                        sh "docker push ${JAVA_IMAGE}:${env.VERSION}"
                        sh "docker push ${JAVA_IMAGE}:latest"
                    }
                }
            }
        }

        stage('Deploy to Staging') {
            when {
                branch 'main'
            }
            steps {
                sh '''
                    kubectl config use-context staging
                    kubectl set image deployment/python-api \
                        api=${PYTHON_IMAGE}:${VERSION} -n staging
                    kubectl set image deployment/java-backend \
                        backend=${JAVA_IMAGE}:${VERSION} -n staging
                    kubectl rollout status deployment/python-api -n staging
                    kubectl rollout status deployment/java-backend -n staging
                '''
            }
        }

        stage('Smoke Tests') {
            when {
                branch 'main'
            }
            steps {
                sh '''
                    sleep 30
                    curl -f http://staging-api.mycompany.com/health
                    curl -f http://staging-backend.mycompany.com/actuator/health
                '''
            }
        }

        stage('Deploy to Production') {
            when {
                branch 'main'
            }
            input {
                message 'Deploy to production?'
                ok 'Deploy'
            }
            steps {
                sh '''
                    kubectl config use-context production
                    kubectl set image deployment/python-api \
                        api=${PYTHON_IMAGE}:${VERSION} -n production
                    kubectl set image deployment/java-backend \
                        backend=${JAVA_IMAGE}:${VERSION} -n production
                    kubectl rollout status deployment/python-api -n production
                    kubectl rollout status deployment/java-backend -n production
                '''
            }
        }
    }

    post {
        always {
            cleanWs()
        }
        success {
            slackSend(
                color: 'good',
                message: "✅ Build ${env.BUILD_NUMBER} succeeded! Deployed ${env.VERSION} to production."
            )
        }
        failure {
            slackSend(
                color: 'danger',
                message: "❌ Build ${env.BUILD_NUMBER} failed! Check ${env.BUILD_URL}"
            )
        }
    }
}

// Jenkins Kubernetes agent configuration
pipeline {
    agent {
        kubernetes {
            yaml '''
                apiVersion: v1
                kind: Pod
                spec:
                  containers:
                    - name: maven
                      image: maven:3.9-eclipse-temurin-17
                      command: ['cat']
                      tty: true
                    - name: python
                      image: python:3.11-slim
                      command: ['cat']
                      tty: true
                    - name: docker
                      image: docker:24-dind
                      securityContext:
                        privileged: true
                    - name: kubectl
                      image: bitnami/kubectl:latest
                      command: ['cat']
                      tty: true
                  volumes:
                    - name: docker-sock
                      hostPath:
                        path: /var/run/docker.sock
            '''
        }
    }

    stages {
        stage('Build Java') {
            steps {
                container('maven') {
                    sh 'mvn clean package'
                }
            }
        }
        stage('Build Python') {
            steps {
                container('python') {
                    sh 'pip install -r requirements.txt && pytest'
                }
            }
        }
        stage('Build Docker') {
            steps {
                container('docker') {
                    sh 'docker build -t myapp:latest .'
                }
            }
        }
        stage('Deploy') {
            steps {
                container('kubectl') {
                    sh 'kubectl apply -f k8s/'
                }
            }
        }
    }
}

# main.tf — Terraform configuration for AWS infrastructure

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # Remote state backend (CRITICAL for teams)
  backend "s3" {
    bucket         = "mycompany-terraform-state"
    key            = "devops-app/production/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "terraform-locks"
  }
}

# Configure the AWS Provider
provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = "devops-app"
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

# Variables (defined in variables.tf or passed at runtime)
variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "production"
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t3.medium"
}

# Data source: Get the latest Amazon Linux 2 AMI
data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

# Resource: VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.environment}-vpc"
  }
}

# Resource: Public Subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "${var.aws_region}a"
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-subnet"
  }
}

# Resource: Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.environment}-igw"
  }
}

# Resource: Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.environment}-public-rt"
  }
}

# Resource: Security Group
resource "aws_security_group" "app" {
  name_prefix = "${var.environment}-app-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-app-sg"
  }
}

# Resource: EC2 Instance for Python API
resource "aws_instance" "python_api" {
  ami                    = data.aws_ami.amazon_linux.id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.public.id
  vpc_security_group_ids = [aws_security_group.app.id]

  user_data = base64encode(templatefile("${path.module}/bootstrap.sh", {
    app_name = "python-api"
  }))

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  tags = {
    Name = "${var.environment}-python-api"
  }
}

# Resource: Application Load Balancer
resource "aws_lb" "main" {
  name               = "${var.environment}-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.app.id]
  subnets            = [aws_subnet.public.id]

  enable_deletion_protection = var.environment == "production"

  tags = {
    Name = "${var.environment}-alb"
  }
}

# Outputs
output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}

output "instance_public_ip" {
  description = "Public IP of the Python API instance"
  value       = aws_instance.python_api.public_ip
}

output "load_balancer_dns" {
  description = "DNS name of the load balancer"
  value       = aws_lb.main.dns_name
}

# modules/vpc/main.tf — Reusable VPC module
variable "environment" {
  type = string
}

variable "cidr_block" {
  type    = string
  default = "10.0.0.0/16"
}

variable "availability_zones" {
  type    = list(string)
  default = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

resource "aws_vpc" "this" {
  cidr_block           = var.cidr_block
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = "${var.environment}-vpc"
    Environment = var.environment
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.availability_zones)
  vpc_id                  = aws_vpc.this.id
  cidr_block              = cidrsubnet(var.cidr_block, 8, count.index)
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.environment}-igw"
  }
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "internet_gateway_id" {
  value = aws_internet_gateway.this.id
}

