// Custom metrics in Spring Boot
package com.mycompany.metrics;

import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import io.micrometer.core.instrument.Gauge;
import org.springframework.stereotype.Component;
import java.util.concurrent.atomic.AtomicInteger;

@Component
public class BusinessMetrics {

    private final Counter orderCounter;
    private final Counter failedOrderCounter;
    private final Timer orderProcessingTimer;
    private final AtomicInteger activeOrders = new AtomicInteger(0);

    public BusinessMetrics(MeterRegistry registry) {
        this.orderCounter = Counter.builder("orders.created")
            .description("Total orders created")
            .tag("service", "backend")
            .register(registry);

        this.failedOrderCounter = Counter.builder("orders.failed")
            .description("Total failed orders")
            .tag("service", "backend")
            .register(registry);

        this.orderProcessingTimer = Timer.builder("order.processing.time")
            .description("Order processing time")
            .publishPercentiles(0.5, 0.95, 0.99)
            .register(registry);

        Gauge.builder("orders.active", activeOrders, AtomicInteger::get)
            .description("Currently active orders")
            .register(registry);
    }

    public void recordOrderCreated() {
        orderCounter.increment();
    }

    public void recordOrderFailed() {
        failedOrderCounter.increment();
    }

    public Timer.Sample startOrderTimer() {
        activeOrders.incrementAndGet();
        return Timer.start();
    }

    public void stopOrderTimer(Timer.Sample sample) {
        activeOrders.decrementAndGet();
        sample.stop(orderProcessingTimer);
    }
}

